[DataContractAttribute, SysOperationGroupAttribute('Filter', '@MET:vrFilter', '1'), SysOperationGroupAttribute('GroupBy', '@MET:vrGroupBy', '2')]
public class METVendorRebateOffRemittanceCalcContract extends METSysOperationTaskDataContract
{
    TransDate asOfDate;
    TransDate reversalDate;
    InventSiteId inventSite;
    NoYesId groupByDepartment;
    NoYesId groupByChargeCode;

    str packedQuery;

}

Method.Source:
/// <summary>
/// Query with ranges set by user
/// </summary>
/// <param name = "_packedQuery">Packed query value</param>
/// <returns>Query string</returns>
[
    DataMemberAttribute,
    AifQueryTypeAttribute('_packedQuery', queryStr(METVendorRebateProcessQuery))
]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;

    return packedQuery;
}

/// <summary>
/// Validate the contract values
/// </summary>
/// <returns>true if validation is successful otherwise false</returns>
public boolean validate()
{
    boolean ret;

    ret = super();

    if(!groupByChargeCode && !groupByDepartment)
    {
        ret = ret && checkFailed('Select group by department or charge code or both');
    }

    return ret;
}

/// <summary>
/// Method to get query object from packedQuery
/// </summary>
/// <returns><c>Query</c> object from packedQuery</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

/// <summary>
/// Process to look for transactions on this date
/// </summary>
/// <param name = "_asOfDate">Date value set by user</param>
/// <returns>Transaction date</returns>
[DataMemberAttribute, SysOperationLabel('@MET:vrAsOfDate'),
    SysOperationGroupMemberAttribute('Filter'),
    SysOperationDisplayOrder('1')]
public TransDate parmAsOfDate(TransDate _asOfDate = asOfDate)
{
    asOfDate = _asOfDate;

    return asOfDate;
}

/// <summary>
/// Reversal date to be set on journal
/// </summary>
/// <param name = "_reversalDate">Transaction date</param>
/// <returns>Transaction date</returns>
[DataMemberAttribute, SysOperationLabel('@MET:vrReversalDate'), 
    SysOperationGroupMemberAttribute('Filter'),
    SysOperationDisplayOrder('2')]
public TransDate parmReversalDate(TransDate _reversalDate = reversalDate)
{
    reversalDate = _reversalDate;

    return reversalDate;
}

/// <summary>
/// Inventory site
/// </summary>
/// <param name = "_inventSite">Inventory site</param>
/// <returns>Inventory site</returns>
[DataMemberAttribute, SysOperationLabel('@MET:Site'),
    SysOperationGroupMemberAttribute('Filter'),
    SysOperationDisplayOrder('3')]
public InventSiteId parmInventSite(InventSiteId _inventSite = inventSite)
{
    inventSite = _inventSite;

    return inventSite;
}

/// <summary>
/// Should the journals be grouped by department.
/// </summary>
/// <param name = "_groupByDepartment">Boolean flag</param>
/// <returns>Boolean value</returns>
[DataMemberAttribute, SysOperationLabel('@MET:vrGroupByDepartment'),
    SysOperationGroupMemberAttribute('GroupBy'),
    SysOperationDisplayOrder('1')]
public NoYes parmGroupByDepartment(NoYes _groupByDepartment = groupByDepartment)
{
    groupByDepartment = _groupByDepartment;

    return groupByDepartment;
}

/// <summary>
/// Should group charge codes
/// </summary>
/// <param name = "_groupByChargeCode">Boolean flag</param>
/// <returns>Boolean flag</returns>
[DataMemberAttribute, SysOperationLabel('@MET:vrGroupByChargeCode'),
    SysOperationGroupMemberAttribute('GroupBy'),
    SysOperationDisplayOrder('2')]
public NoYes parmGroupByChargeCode(NoYes _groupByChargeCode = groupByChargeCode)
{
    groupByChargeCode = _groupByChargeCode;

    return groupByChargeCode;
}
